//! Golden `.rd` files. They were generated by this crate (not taken from any other software).
//! Regenerate after an intended format change with `DARKBURN_BLESS=1 cargo test -p darkburn-ruida --test golden`.

mod common;

use std::path::PathBuf;

use darkburn_ruida::{Magic, RdJob};

fn golden(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("golden").join(name)
}

fn check(name: &str, job: &RdJob, magic: Magic) {
    let bytes = job.to_rd_file(magic).unwrap();
    let path = golden(name);
    if std::env::var_os("DARKBURN_BLESS").is_some() {
        std::fs::write(&path, &bytes).unwrap();
    }
    let want = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}; run with DARKBURN_BLESS=1 once", path.display()));
    assert_eq!(bytes, want, "{name} changed; bless if intended");
    // And it reads back into the same job, with and without a known magic.
    assert_eq!(RdJob::from_rd_file(&want, Some(magic)).unwrap(), job.quantized());
    assert_eq!(RdJob::from_rd_file(&want, None).unwrap(), job.quantized());
}

#[test]
fn golden_square() {
    check("square.rd", &common::square_job((10.0, 10.0), 50.0, 40.0), Magic::DEFAULT);
}

#[test]
fn golden_mixed() {
    check("mixed.rd", &common::mixed_job(), Magic::DEFAULT);
}

#[test]
fn golden_mixed_magic_11() {
    check("mixed_magic11.rd", &common::mixed_job(), Magic(0x11));
}

#[test]
fn golden_file_starts_with_header() {
    let bytes = std::fs::read(golden("square.rd")).unwrap();
    let logical = darkburn_ruida::swizzle::unswizzle(&bytes, Magic::DEFAULT);
    // D8 10 (measured from machine zero), E6 01 (absolute), F0 (reference point), ... ends with D7.
    assert_eq!(&logical[..5], &[0xD8, 0x10, 0xE6, 0x01, 0xF0]);
    assert_eq!(logical.last(), Some(&0xD7));
}
